  @Test
  @DisplayName("rejects a signature made with another key")
  void test_other_key() throws Exception {
    Document document = parse(new Fixture().xml());
    sign(assertion(document), otherKeys.getPrivate());
    assertRejected(encode(document));
  }

  @Test
  @DisplayName("rejects an assertion modified after signing")
  void test_tampered() throws Exception {
    Document document = parse(new Fixture().xml());
    sign(assertion(document), idpKeys.getPrivate());
    document.getElementsByTagNameNS(SamlResponseValidator.ASSERTION, "NameID").item(0)
        .setTextContent("admin@example.com");
    assertRejected(encode(document));
  }

  @Test
  @DisplayName("rejects a signed assertion wrapped next to a forged one")
  void test_signature_wrapping() throws Exception {
    Document document = parse(new Fixture().xml());
    Element signed = assertion(document);
    sign(signed, idpKeys.getPrivate());
    Element forged = (Element) signed.cloneNode(true);
    forged.setAttribute("ID", "_forged");
    forged.removeChild(
        forged.getElementsByTagNameNS("http://www.w3.org/2000/09/xmldsig#", "Signature").item(0));
    forged.getElementsByTagNameNS(SamlResponseValidator.ASSERTION, "NameID").item(0)
        .setTextContent("admin@example.com");
    document.getDocumentElement().insertBefore(forged, signed);
    assertRejected(encode(document));
  }

  @Test
  @DisplayName("rejects a response signature that does not reference the response")
  void test_signature_for_other_element() throws Exception {
    Document document = parse(new Fixture().xml());
    Element response = document.getDocumentElement();
    sign(response, idpKeys.getPrivate());
    // The same ID moves to the assertion: the reference would now resolve to another element.
    response.setAttribute("ID", "_moved");
    assertRejected(encode(document));
  }

