  @Test
  @DisplayName("reads the whole NameID even when a comment splits it")
  void test_comment_in_name_id() throws Exception {
    Fixture fixture = new Fixture();
    fixture.nameId = "alice@example.com.evil.com";
    Document document = parse(fixture.xml());
    sign(assertion(document), idpKeys.getPrivate());
    Node nameId =
        document.getElementsByTagNameNS(SamlResponseValidator.ASSERTION, "NameID").item(0);
    nameId.setTextContent("");
    nameId.appendChild(document.createTextNode("alice@example.com"));
    nameId.appendChild(document.createComment(""));
    nameId.appendChild(document.createTextNode(".evil.com"));
    Assertions.assertEquals("alice@example.com.evil.com",
        SamlResponseValidator.validate(encode(document), expected()).getNameId());
  }
